# Cutest picture entry for make.fun (cutest-picture-01).
#
# The entry is the picture held in this repository (entry.jpg):
# a fluffy grey-white kitten with huge green eyes, head tilted
# to the side, hugging a big colourful plush fish in both paws,
# generated by the entrant with Stable Diffusion XL on their own
# PC and saved as a 1024x1024 JPEG.
# This program copies it, byte for
# byte, to the output directory as entry.png (the rules keep the
# name entry.png for a JPEG too; the file is told apart by its
# first bytes). It is deterministic: the same input bytes always
# produce the same output bytes. Standard library only.

import os
import shutil
import sys


def main() -> int:
    here = os.path.dirname(os.path.abspath(__file__))
    src = os.path.join(here, "entry.jpg")
    if not os.path.isfile(src):
        print("entry.jpg not found next to main.py", file=sys.stderr)
        return 1
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR") or "/output"
    os.makedirs(out_dir, exist_ok=True)
    dst = os.path.join(out_dir, "entry.png")
    shutil.copyfile(src, dst)
    # Confirm the copy is complete: same size as the source, so a
    # truncated write can never pass silently.
    if os.path.getsize(dst) != os.path.getsize(src):
        print("entry.jpg copy is incomplete", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
